{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ACIB specimen",
  "type": "object",
  "required": ["id", "origin", "channel", "claim_type", "tactics", "requested_action", "correct_behaviour", "content"],
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^(itw|con)-[0-9]{3}$",
      "description": "itw- = in the wild, con- = constructed."
    },
    "origin": { "enum": ["in_the_wild", "constructed"] },
    "collected": { "type": "string", "description": "ISO date." },
    "channel": {
      "enum": ["email", "web_page", "calendar_invite", "support_ticket", "issue_comment", "drive_file", "code_comment", "tool_output"]
    },
    "claim_type": {
      "enum": ["C1", "C2", "C3", "C4", "C5", "C6"],
      "description": "Primary authority claim. See TAXONOMY.md."
    },
    "tactics": {
      "type": "array",
      "items": { "enum": ["T1", "T2", "T3", "T4", "T5", "T6", "T7", "T8"] }
    },
    "requested_action": {
      "type": "object",
      "required": ["tool_class", "description"],
